import{_ as t,o,c as l,a5 as s}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-28-view-mail-template/report3_spec.md","filePath":"feature/content-task-workflow/3-6-28-view-mail-template/report3_spec.md"}'),i={name:"feature/content-task-workflow/3-6-28-view-mail-template/report3_spec.md"};function r(a,e,n,p,c,d){return o(),l("div",null,[...e[0]||(e[0]=[s('<p><strong>3.6.28 View Mail Template</strong></p><p><strong>Function Trigger</strong></p><p>A Workspace member (OWNER, MANAGER or CREATOR) opens <code>/workspaces/:id/mail-templates</code> to browse the saved email templates, optionally including the system starter templates.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: OWNER, MANAGER, CREATOR of the Workspace. CLIENT is not allowed.</li><li><strong>Purpose</strong>: Let a member find a template to reuse, clone, edit or send.</li><li><strong>Interface</strong>: A list page with search and pagination showing template name, subject preview, creation date, type (Workspace / System) and attachment count. System templates carry a &quot;System&quot; chip and only offer &quot;Use template&quot; (clone).</li><li><strong>Data Processing</strong>: The system queries non-deleted <code>mail_templates</code> of the Workspace and, when requested, the <code>SYSTEM_DEFAULT</code> templates, then returns a paged list.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Mail Template List View:</p><ul><li>Search box, &quot;Include system templates&quot; toggle.</li><li>Table/list: name, subject preview (120 chars), type chip, attachment count, created date.</li><li>&quot;Create Template&quot; button (entry point to 3.6.29).</li><li>Per-row actions: Edit, Delete (entry points to 3.6.30/3.6.31), Send (entry point to 3.6.32), Use template (system rows).</li><li>Link to the send history page (batches).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Workspace identifier (path param).</li><li><strong>Input optional</strong>: <code>includeSystem</code>, <code>q</code>, <code>page</code>, <code>size</code>.</li><li><strong>System data</strong>: <code>mail_templates</code> (MongoDB) scoped to the Workspace plus <code>SYSTEM_DEFAULT</code> rows.</li><li><strong>Output</strong>: paged list <code>[{id, name, subject, type, attachmentCount, createdAt}]</code>.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li>Only OWNER/MANAGER/CREATOR members of the Workspace may view.</li><li>Soft-deleted templates (<code>deletedAt != null</code>) never appear.</li><li>System templates are visible to every Workspace and are read-only there.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>No access → 403 <code>FORBIDDEN</code>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>A member opens <code>/workspaces/:id/mail-templates</code>.</li></ol></li><li><ol start="2"><li>The system verifies the member&#39;s role in the Workspace.</li></ol></li><li><ol start="3"><li>The system returns the paged template list (with system templates when requested).</li></ol></li><li><ol start="4"><li>The page renders the list with loading, empty and error states.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Caller is not a permitted member (including CLIENT) → 403 <code>FORBIDDEN</code>.</li><li>3.a1: No templates → empty state with a &quot;Create Template&quot; prompt.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>None — read-only view.</li></ul>',14)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
